async function fetchAddressByStraps(searchText) {
        const term = (searchText || '').trim();
        if (/^\d+$/.test(term)) {
            // Digit-only queries mostly match subdivision/plat stub addresses that
            // have no corresponding ParcelMarket record, so the strap-matching lookup
            // below comes back empty. Fall back to the classic contains search instead
            // (SitusAll, so secondary address lines match too).
            await fetchTotalCount(term, 'SitusAll', 'PM');
            return;
        }
        if (!/^\d+\s/.test(term)) {
            // Street-only searches (no house number) match whole roads â the
            // strap-eq filter below would need one clause per parcel and the
            // resulting URL blows past the server's query-string limit (404),
            // so use the paged contains search. SitusAll covers every address
            // line on the parcel, so roads that only appear as a parcel's
            // secondary address still match.
            await fetchTotalCount(term, 'SitusAll', 'PM');
            return;
        }
        try {
            const response = await fetch(`/api/v1/SiteAddress/search?q=${encodeURIComponent(searchText)}&max=100`);
            if (!response.ok) {
                console.error('Address search failed:', response.status);
                $("#resultsLoadingDiv").prop('style', 'display:none');
                return;
            }
            const addresses = await response.json();
            if (!addresses || addresses.length === 0) {
                // An address the site-address table doesn't carry can still exist in
                // ParcelMarket â give the classic contains search a chance
                // before giving up, the same fallback the autocomplete uses.
                await fetchTotalCount(term, 'SitusAll', 'PM');
                return;
            }
            // A multi-address parcel returns one row per address line â dedupe so the
            // grid filter has one strap clause per parcel.
            const uniqueStraps = [...new Set(addresses.map(a => a.Strap.trim()))];
            if (uniqueStraps.length > 40) {
                // Too many parcels to name individually in the filter URL
                // (query-string limit) â fall back to the paged contains search.
                await fetchTotalCount(term, 'SitusAll', 'PM');
                return;
            }
            const filters = {
                logic: "or",
                filters: uniqueStraps.map(strap => ({
                    field: "strap",
                    operator: "eq",
                    value: strap
                }))
            };
            await BindKendoGrid('/api/v1/ParcelMarket', filters, 'PM');
            $("#resultsLoadingDiv").prop('style', 'display:none');
        } catch (err) {
            console.error('Address search error:', err);
            $("#resultsLoadingDiv").prop('style', 'display:none');
        }
    }
    async function fetchTotalCount(filter, col, tableName, col2, page) {
        if (tableName === "PM" && page !== "MapInfoTabService") {
            let urlForSitus = `/api/v1/ParcelMarket?$select=ParcelMarketId&$filter=contains(${col}, '${filter}')`;
            var getTotalCountData = await _helper.getDataAsync(urlForSitus);
            if (getTotalCountData !== undefined && getTotalCountData !== null) {
                fetchResult(filter, getTotalCountData.value.length, col);
            } else {
                $("#resultsLoadingDiv").removeAttr('style');
                $("#resultsLoadingDiv").prop('style', 'display:none');
                alert('Search failed. Please try again.');
            }
        }
        if (tableName === "PM" && page == "MapInfoTabService") {
            let urlForSitus = `/api/v1/ParcelMarket?$select=ParcelMarketId&$filter=contains(${col}, '${filter}')`;
            var getTotalCountData = await _helper.getDataAsync(urlForSitus);
            if (getTotalCountData !== undefined && getTotalCountData !== null) {
                let url = `/api/v1/ParcelMarket?$format=json&$apply=filter(${col} eq '${escapeString(filter)}')  &$count=true`;
                await bindMapInfoServiceResults(url, page);
            } else {
                $(".resultsLoaderClassForPRC").text("No Data Found! Kindly check URL.");                
            }
        }
